<?php declare(strict_types=1); namespace Tests\Integration\Review; use App\Domain\Identity\Entity\User;use App\Domain\Review\Entity\NotebookAnalysisExecution;use App\Domain\Review\Enum\NotebookAnalysisStatus;use App\Infrastructure\Persistence\Doctrine\DoctrineEntityManagerFactory;use App\Infrastructure\Persistence\Doctrine\Identity\DoctrineUserRepository;use App\Infrastructure\Persistence\Doctrine\Review\DoctrineNotebookAnalysisExecutionRepository;use PHPUnit\Framework\TestCase;final class DoctrineNotebookAnalysisExecutionRepositoryTest extends TestCase {public function testIsolatesNotebookAnalysisByOwnerAndClaimsOnce():void{$em=DoctrineEntityManagerFactory::create();$connection=$em->getConnection();$suffix=bin2hex(random_bytes(8));$userId='00000000-0000-4000-8000-'.substr($suffix,0,12);$otherId='00000000-0000-4000-8001-'.substr($suffix,0,12);$notebookId='10000000-0000-4000-8000-'.substr($suffix,0,12);$executionId='20000000-0000-4000-8000-'.substr($suffix,0,12);$now=new \DateTimeImmutable('now',new \DateTimeZone('UTC'));$users=new DoctrineUserRepository($em);$executions=new DoctrineNotebookAnalysisExecutionRepository($em);$connection->beginTransaction();try{$users->save(new User($userId,'review-'.$suffix.'@example.test','Review integration',null,'ACTIVE',['USER']));$users->save(new User($otherId,'review-other-'.$suffix.'@example.test','Other integration',null,'ACTIVE',['USER']));$em->flush();$connection->executeStatement("INSERT INTO notebooks (id,user_id,name,type,mode,status,filters,created_at,updated_at) VALUES (:id,:userId,'Review integration','PRACTICE','STUDY','FINISHED','{}',UTC_TIMESTAMP(),UTC_TIMESTAMP())",['id'=>$notebookId,'userId'=>$userId]);$executions->save(new NotebookAnalysisExecution($executionId,$notebookId,'v1',NotebookAnalysisStatus::PENDING,0,null,null,null,null,null,null,null,$now));$em->flush();$em->clear();self::assertNotNull($executions->findForNotebookUser($notebookId,$userId));self::assertNull($executions->findForNotebookUser($notebookId,$otherId));$job=$executions->claimNextPending($now);self::assertNotNull($job);self::assertSame($userId,$job->userId);self::assertSame(NotebookAnalysisStatus::PROCESSING,$job->execution->status);self::assertNull($executions->claimNextPending($now));}finally{$connection->rollBack();$em->clear();}}}
